    "question": "Q378. [Advanced NEET Challenge] In acidic medium, one mole of potassium permanganate ($\\text{KMnO}_4$) oxidizes how many moles of ferrous ions ($\\text{Fe}^{2+}$) to ferric ions ($\\text{Fe}^{3+}$)?",
    "options": {
      "A": "$1\\text{ mole}$",
      "B": "$5\\text{ moles}$",
      "C": "$3\\text{ moles}$",
      "D": "$6\\text{ moles}$"
    },
