    "explanation": "1. CONCEPT & PRINCIPLE:\nOrigin of color in transition metal complexes ($d-d$ electronic transitions).\n\n2. GIVEN INFORMATION / DATA:\n$Sc^{3+}$ ($3d^0$), $Zn^{2+}$ ($3d^{10}$), $Cu^{2+}$ ($3d^9$), $Fe^{3+}$ ($3d^5$), $Cr^{3+}$ ($3d^3$).\n\n3. FORMULA / EQUATION:\nColor requires absorption of visible light by $d-d$ transition between split $d$-orbitals (requires $1 \\le d \\le 9$ electrons).\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. Color in transition metal ions arises from excitation of an electron from lower $t_{2g}$ to higher $e_g$ orbitals (or vice-versa) in the presence of ligand field ($d-d$ transitions).\n2. For $Sc^{3+}$ ($Z=21$), configuration is $[Ar]3d^0$. With no $d$-electrons, no $d-d$ transition is possible, so it is colorless.\n3. For $Zn^{2+}$ ($Z=30$), configuration is $[Ar]3d^{10}$. With completely filled $d$-orbitals, no vacancy exists for electronic excitation, so it is colorless.\n4. $Cu^{2+}$ (blue), $Fe^{3+}$ (yellow), and $Cr^{3+}$ (violet) all have partially filled $d$-orbitals and are colored.\n\n5. FINAL CONCLUSION:\n$\\text{Sc}^{3+}$ ($d^0$) and $\\text{Zn}^{2+}$ ($d^{10}$)\n\n6. OPTION ANALYSIS & COMMON TRAPS:\n$Cu^{2+}$ is characteristic blue; $Fe^{3+}$ is yellow/brown; $Cr^{3+}$ is deep green/violet.",
