      "given": "$Sc^{3+}$ ($3d^0$), $Zn^{2+}$ ($3d^{10}$), $Cu^{2+}$ ($3d^9$), $Fe^{3+}$ ($3d^5$), $Cr^{3+}$ ($3d^3$).",
