    "correctAnswer": "D",
    "correctIndex": 3,
    "explanation": "1. CONCEPT & PRINCIPLE:\nProperties of interstitial compounds formed by transition metals.\n\n2. GIVEN INFORMATION / DATA:\nTransition metals trapping small atoms (H, B, C, N) in interstitial crystal voids (e.g., $TiC$, $Fe_3H$, $Mn_4N$).\n\n3. FORMULA / EQUATION:\nNon-stoichiometric interstitial alloys: High hardness, high MP, metallic conductivity retained.\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. Transition metals have open crystal lattices with interstitial spaces that accommodate small non-metal atoms like carbon, nitrogen, or hydrogen.\n2. Because metal-metal bonding is reinforced by covalent metal-nonmetal interactions, interstitial compounds exhibit extremely high melting points (often higher than pure metals).\n3. They are exceedingly hard (some approach diamond in hardness, such as titanium carbide $TiC$).\n4. Importantly, they retain metallic electrical and thermal conductivity because valence conduction bands remain partially occupied.\n5. They are chemically inert and non-stoichiometric.\n\n5. FINAL CONCLUSION:\nThey are chemically inert, have very high melting points, and retain metallic electrical conductivity.\n\n6. OPTION ANALYSIS & COMMON TRAPS:\nThey are neither ionic nor low melting; they are non-stoichiometric, extremely hard, and retain metallic conductivity.",
