      "finalAnswer": "$5\\text{ moles}$",
      "whyOtherOptionsWrong": "$6\\text{ moles}$ is the equivalent factor for $K_2Cr_2O_7$; $3\\text{ moles}$ corresponds to alkaline permanganate reduction to $MnO_2$."
