    "question": "Q493. [Advanced NEET Challenge] In acidic medium, one mole of potassium permanganate ($\\text{KMnO}_4$) oxidizes how many moles of ferrous ions ($\\text{Fe}^{2+}$) to ferric ions ($\\text{Fe}^{3+}$)?",
