    "correctAnswer": "A",
    "correctIndex": 0,
    "explanation": "1. CONCEPT & PRINCIPLE:\nStoichiometry of redox titrations using acidified $KMnO_4$.\n\n2. GIVEN INFORMATION / DATA:\nPermanganate reduction: $MnO_4^- + 8H^+ + 5e^- \\rightarrow Mn^{2+} + 4H_2O$; Ferrous oxidation: $Fe^{2+} \\rightarrow Fe^{3+} + e^-$.\n\n3. FORMULA / EQUATION:\n$1\\text{ mol } MnO_4^- \\equiv 5\\text{ equivalents of electrons} \\equiv 5\\text{ moles of } Fe^{2+}$.\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. In acidic solution, manganese in $MnO_4^-$ is reduced from $+7$ to $+2$, accepting $5$ electrons: $MnO_4^- + 8H^+ + 5e^- \\rightarrow Mn^{2+} + 4H_2O$.\n2. Each ferrous ion ($Fe^{2+}$) loses 1 electron upon oxidation to ferric ion ($Fe^{3+}$): $Fe^{2+} \\rightarrow Fe^{3+} + e^-$.\n3. Multiplying the ferrous half-reaction by 5 balances electron transfer: $MnO_4^- + 8H^+ + 5Fe^{2+} \\rightarrow Mn^{2+} + 5Fe^{3+} + 4H_2O$.\n4. Thus, exactly 1 mole of $KMnO_4$ reacts quantitatively with 5 moles of $Fe^{2+}$.\n\n5. FINAL CONCLUSION:\n$5\\text{ moles}$\n\n6. OPTION ANALYSIS & COMMON TRAPS:\n$6\\text{ moles}$ is the equivalent factor for $K_2Cr_2O_7$; $3\\text{ moles}$ corresponds to alkaline permanganate reduction to $MnO_2$.",
